[ExtensionOf(tableStr(CredManAccountStatusTable))]
final class METCredManAccountStatusTable_Extension
{
}

Method.Source:
/// <summary>
/// validate the condition <c> CredManAccountHeldType </c> to set functional location records
/// </summary>
/// <param name = "CredManAccountHeldType">CredManAccountHeldType</param>
protected boolean isValidAccountHeldType(CredManAccountHeldType _credManAccountHeldType)
{


    // Call base logic
    boolean isValid = next isValidAccountHeldType(_credManAccountHeldType);

    // Add  additional valid enum value
    if (!isValid)
    {
        isValid = (_credManAccountHeldType == CredManAccountHeldType::METSalesinvoice);
    }

    return isValid;
}

/// <summary>
/// Gets <c>CustVendorBlocked</c> enumeration value based on Invoicing and delivery on hold value.
/// </summary>
/// <returns>
/// Returns the stopped field value of customer/vendor record.
/// </returns>
protected internal CustVendorBlocked getCustVendorBlocked()
{
    CustVendorBlocked custVendorBlocked = next getCustVendorBlocked();

    if (this.CustBlocked == CredManAccountHeldType::METSalesinvoice)
    {
        custVendorBlocked = CustVendorBlocked::METSalesinvoice;
    }

    return custVendorBlocked;
}
